import React, { useState } from 'react';
import { checkboxStyleKeys, getCheckboxState, getNextCheckboxState } from '../lib/core';
import type { CheckboxCheckedState } from '../lib/core';
import styles from './checkbox.module.scss';

export interface CheckboxProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'defaultChecked'> {
	checked?: CheckboxCheckedState;
	defaultChecked?: CheckboxCheckedState;
	onCheckedChange?: (checked: CheckboxCheckedState) => void;
}

const Checkbox = React.forwardRef<HTMLButtonElement, CheckboxProps>(({ className = '', checked, defaultChecked = false, disabled, onCheckedChange, ...props }, ref) => {
	const [internalChecked, setInternalChecked] = useState<CheckboxCheckedState>(defaultChecked);
	const isChecked = checked !== undefined ? checked : internalChecked;
	const state = getCheckboxState(isChecked);

	function handleClick(event: React.MouseEvent<HTMLButtonElement>) {
		const next = getNextCheckboxState(isChecked);

		if (checked === undefined) {
			setInternalChecked(next);
		}

		onCheckedChange?.(next);
		props.onClick?.(event);
	}

	const ariaChecked = state === 'checked' ? 'true' : state === 'mixed' ? 'mixed' : 'false';

	return (
		<button
			ref={ref}
			type="button"
			role="checkbox"
			aria-checked={ariaChecked}
			data-state={state}
			disabled={disabled}
			className={`${styles[checkboxStyleKeys.root]} ${className}`}
			{...props}
			onClick={handleClick}>
			<span className={styles[checkboxStyleKeys.indicator]}>
				{state === 'checked' && (
					<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
						<path d="M20 6 9 17l-5-5" />
					</svg>
				)}
				{state === 'mixed' && (
					<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round">
						<path d="M5 12h14" />
					</svg>
				)}
			</span>
		</button>
	);
});

Checkbox.displayName = 'Checkbox';

export { Checkbox };
export default Checkbox;

@use '../../../styles/variables/colors' as *;

.root {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	width: var(--tile-checkbox-size, 1rem);
	height: var(--tile-checkbox-size, 1rem);
	border-radius: var(--tile-checkbox-radius, #{$radius-sm});
	border: var(--tile-checkbox-border-width, 1px) solid var(--tile-checkbox-border, #{$input});
	background-color: var(--tile-checkbox-background, initial);
	box-shadow: var(--tile-checkbox-shadow, #{$shadow-sm});
	transition:
		background-color $transition-fast,
		border-color $transition-fast,
		box-shadow $transition-fast;
	outline: none;

	&:focus-visible {
		border-color: var(--tile-checkbox-focus-border, #{$ring});
		box-shadow: var(--tile-checkbox-focus-shadow, 0 0 0 1px #{$ring});
		outline: none;
	}

	&:disabled {
		cursor: not-allowed;
		opacity: 0.5;
	}

	&[aria-invalid='true'] {
		border-color: $destructive;
		box-shadow: var(--tile-checkbox-error-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-checkbox-error-focus-shadow, 0 0 0 1px #{$destructive});
		}
	}

	&[data-state='checked'],
	&[data-state='mixed'] {
		border-color: var(--tile-checkbox-checked-border, #{$primary});
		background-color: var(--tile-checkbox-checked-background, #{$primary});
		color: var(--tile-checkbox-checked-color, #{$primary-foreground});
		box-shadow: var(--tile-checkbox-checked-shadow, #{$shadow-sm});

		&:focus-visible {
			box-shadow: var(--tile-checkbox-checked-focus-shadow, 0 0 0 1px #{$ring});
			outline: var(--tile-checkbox-checked-focus-outline, none);
			outline-offset: var(--tile-checkbox-checked-focus-offset, 0px);

			&[aria-invalid='true'] {
				box-shadow: var(--tile-checkbox-error-focus-shadow, 0 0 0 1px #{$destructive});
			}
		}
	}
}

.indicator {
	display: grid;
	place-content: center;
	color: currentColor;

	svg {
		width: var(--tile-checkbox-indicator-size, 0.875rem);
		height: var(--tile-checkbox-indicator-size, 0.875rem);
	}
}
